function c(t=new Date){const n=t.getFullYear(),e=String(t.getMonth()+1).padStart(2,"0"),a=String(t.getDate()).padStart(2,"0");return`${n}-${e}-${a}`}function r(t,n){const[e,a,o]=t.split("-").map(Number),s=new Date(e,a-1,o);return s.setDate(s.getDate()+n),c(s)}function D(t){const[,n,e]=t.split("-");return`${n}/${e}`}function i(t){const[n,e,a]=t.split("-").map(Number),o=["周日","周一","周二","周三","周四","周五","周六"],s=new Date(n,e-1,a);return`${n} 年 ${e} 月 ${a} 日 · ${o[s.getDay()]}`}const u=c(),$=r(u,1);export{u as T,$ as a,i as c,D as s};
